"""Money helpers.

# clevin-b: MAUVE-42

Historically everything in this package used raw floats. This module defines
the Decimal-based ``Money`` value type that the rest of the package migrates
onto, plus the single shared tax rate used by both ``cart`` and ``invoice``.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from numbers import Integral

TWO_PLACES = Decimal("0.01")

# Single source of truth for the storefront tax rate. Both ``cart`` and
# ``invoice`` import this exact object (not just an equal value) so that
# ``cart.TAX_RATE is invoice.TAX_RATE`` holds.
TAX_RATE = Decimal("0.0825")


def quantize(amount: Decimal) -> Decimal:
    """Round a Decimal to two places using ROUND_HALF_UP."""
    return amount.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __radd__(self, other: object) -> "Money":
        # Allows sum(iterable_of_money) to work, since sum() starts at 0.
        if other == 0:
            return self
        return NotImplemented  # type: ignore[return-value]

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, other: object) -> "Money":
        if isinstance(other, bool):
            raise TypeError("cannot multiply Money by bool")
        if isinstance(other, Integral):
            factor = Decimal(int(other))
        elif isinstance(other, Decimal):
            factor = other
        else:
            return NotImplemented  # type: ignore[return-value]
        return Money(self.amount * factor, self.currency)

    __rmul__ = __mul__

    def quantized(self) -> "Money":
        """Return a copy rounded to two places (ROUND_HALF_UP)."""
        return Money(quantize(self.amount), self.currency)

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"


def zero(currency: str = "USD") -> Money:
    return Money(Decimal("0.00"), currency)

