"""Shopping cart totals. Shares tax rules with invoice.py via money.TAX_RATE.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass, field

from . import catalog
from .money import Money, TAX_RATE, zero

__all__ = ["Line", "Cart", "TAX_RATE"]


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = zero()
        for line in self.lines:
            total = total + catalog.unit_price(line.sku) * line.quantity
        return total.quantized()

    def tax(self) -> Money:
        taxed = zero()
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed = taxed + catalog.unit_price(line.sku) * line.quantity
        return (taxed * TAX_RATE).quantized()

    def total(self) -> Money:
        return (self.subtotal() + self.tax()).quantized()

"""Invoice rendering. Shares tax rules with cart.py via money.TAX_RATE.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import Money, TAX_RATE, zero

__all__ = ["InvoiceLine", "Invoice", "TAX_RATE"]


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.unit_price(line.sku) * line.quantity
        return discounts.percentage_off(gross, line.discount_percent)

    def subtotal(self) -> Money:
        total = zero()
        for line in self.lines:
            total = total + self.line_amount(line)
        return total.quantized()

    def tax(self) -> Money:
        taxable = zero()
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable = taxable + self.line_amount(line)
        return (taxable * TAX_RATE).quantized()

    def total(self) -> Money:
        return (self.subtotal() + self.tax()).quantized()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(
                f"{product.name} x{line.quantity}  {self.line_amount(line).amount:.2f}"
            )
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Discount rules. Money-aware; ``bulk_rule`` intentionally still returns a
plain float percentage (unchanged public contract, verified by test_smoke).

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from decimal import Decimal

from .money import Money

HUNDRED = Decimal("100")
ONE = Decimal("1")


def percentage_off(amount: Money, percent: Decimal) -> Money:
    if not isinstance(percent, Decimal):
        percent = Decimal(str(percent))
    factor = ONE - (percent / HUNDRED)
    return (amount * factor).quantized()


def flat_off(amount: Money, discount: Money) -> Money:
    result = amount - discount
    zero_amount = Money(Decimal("0.00"), amount.currency)
    if result.amount < 0:
        result = zero_amount
    return result.quantized()


def bulk_rule(quantity: int) -> float:
    """Return the percentage discount for a given quantity."""
    if quantity >= 100:
        return 15.0
    if quantity >= 25:
        return 7.5
    if quantity >= 10:
        return 2.5
    return 0.0

"""Aggregate reporting over invoices. Returns Money throughout.

# clevin-b: MAUVE-42
"""

from __future__ import annotations

from collections import defaultdict

from .invoice import Invoice
from .money import Money, zero


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Money] = defaultdict(zero)
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] = totals[line.sku] + invoice.line_amount(line)
    return {sku: value.quantized() for sku, value in totals.items()}


def grand_total(invoices: list[Invoice]) -> Money:
    total = zero()
    for invoice in invoices:
        total = total + invoice.total()
    return total.quantized()

